/**
 * `npm run tables`: the case-study tables and figure data of the paper, generated from `sim/out/case-study/`
 * (written by `npm run case-study`) into `paper/generated/`. Never edit the generated files by hand.
 *
 *   scenarios.tex  outcome and payload of C1-C6 per strategy (from results.md, the scripted-scenario table)
 *   random.tex     the small random workload, mean and sd over the seeds (from runs.jsonl)
 *   byclass.tex    lost / judged operations per field class, summed over the seeds (from runs.jsonl)
 *   random.dat     loss rate and payload per strategy, read by pgfplots for the figure
 *
 * Only `node:` modules are imported, so the script also runs without the simulator's dependencies.
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const SIM_DIR = join(dirname(fileURLToPath(import.meta.url)), '..');
const IN_DIR = join(SIM_DIR, 'out', 'case-study');
const OUT_DIR = join(SIM_DIR, '..', 'paper', 'generated');

const ORDER = ['lww', 'vv', 'automerge', 'yjs', 'hybrid'];
const LABEL: Record<string, string> = {
  lww: 'LWW',
  vv: 'VV',
  automerge: 'Automerge',
  yjs: 'Yjs',
  hybrid: 'Hybrid',
};
const CLASSES = ['SIMPLE', 'CRITICAL', 'SET', 'APPEND', 'COUNTER', 'RECORD'];
const HEADER = '% Generated by `npm run tables` (sim/scripts/tables.ts) from sim/out/case-study; do not edit.\n';

interface ScenarioRow {
  scenario: string;
  strategy: string;
  finalValue: string;
  lost: number;
  surfaced: number;
  ambiguous: number;
  causalViolations: number;
  openConflicts: number;
  converged: boolean;
  payloadBytes: number;
}

interface Counts {
  ops: number;
  lost: number;
}

interface RunLine {
  config: { name: string; kind: string; strategy: string };
  metrics: Record<string, number | boolean>;
  byClass: Record<string, Counts>;
}

function strategies(present: Iterable<string>): string[] {
  const set = new Set(present);
  return ORDER.filter((s) => set.has(s));
}

/** Rows of the "Scripted scenarios" table of results.md. */
export function parseScenarioTable(markdown: string): ScenarioRow[] {
  const rows: ScenarioRow[] = [];
  for (const line of markdown.split('\n')) {
    const cells = line.split('|').map((c) => c.trim());
    // ['', scenario, strategy, final, lost, surfaced, ambiguous, causal, open, converged, payload, '']
    if (cells.length !== 12 || !/^C\d+$/.test(cells[1] ?? '')) continue;
    const num = (i: number) => Number(cells[i]);
    rows.push({
      scenario: cells[1]!,
      strategy: cells[2]!,
      finalValue: cells[3]!,
      lost: num(4),
      surfaced: num(5),
      ambiguous: num(6),
      causalViolations: num(7),
      openConflicts: num(8),
      converged: cells[9] === 'yes',
      payloadBytes: num(10),
    });
  }
  if (rows.length === 0) throw new Error('no scenario rows found in results.md');
  return rows;
}

/** Short outcome of one scenario run: the losses and conflicts, or the policy applied to an ambiguous pair. */
export function outcomeCell(r: ScenarioRow): string {
  if (!r.converged) return 'diverged';
  if (r.ambiguous > 0 && r.lost === 0 && r.surfaced === 0) {
    if (r.openConflicts > 0) return 'conflict';
    return r.finalValue.includes('(deleted)') ? 'delete wins' : 'edit wins';
  }
  const parts: string[] = [];
  if (r.lost > 0) parts.push(`${r.lost} lost`);
  if (r.surfaced > 0) parts.push(`${r.surfaced} surf.`);
  if (parts.length === 0) parts.push('none');
  return parts.join(', ') + (r.causalViolations > 0 ? '$^{\\ast}$' : '');
}

export function scenariosTex(rows: ScenarioRow[]): string {
  const strats = strategies(rows.map((r) => r.strategy));
  const scenarios = [...new Set(rows.map((r) => r.scenario))].sort();
  const get = (sc: string, st: string) => {
    const r = rows.find((x) => x.scenario === sc && x.strategy === st);
    if (!r) throw new Error(`missing ${sc} ${st}`);
    return r;
  };
  const head = ['', ...strats.map((s) => LABEL[s] ?? s)].join(' & ');
  const out = [HEADER, `\\begin{tabular}{@{}l${'r'.repeat(strats.length)}@{}}`, '\\toprule', `${head} \\\\`, '\\midrule'];
  out.push(`\\multicolumn{${strats.length + 1}}{@{}l}{\\emph{Outcome of the scenario operations}} \\\\`);
  for (const sc of scenarios) out.push(`${sc} & ${strats.map((st) => outcomeCell(get(sc, st))).join(' & ')} \\\\`);
  out.push('\\midrule');
  out.push(`\\multicolumn{${strats.length + 1}}{@{}l}{\\emph{Payload (bytes)}} \\\\`);
  for (const sc of scenarios) out.push(`${sc} & ${strats.map((st) => String(get(sc, st).payloadBytes)).join(' & ')} \\\\`);
  out.push('\\bottomrule', '\\end{tabular}', '');
  return out.join('\n');
}

function mean(xs: number[]): number {
  return xs.reduce((a, b) => a + b, 0) / xs.length;
}

function sd(xs: number[]): number {
  if (xs.length < 2) return 0;
  const m = mean(xs);
  return Math.sqrt(xs.reduce((a, x) => a + (x - m) ** 2, 0) / (xs.length - 1));
}

function pm(xs: number[], scale: number, digits: number): string {
  return `$${(mean(xs) * scale).toFixed(digits)} \\pm ${(sd(xs) * scale).toFixed(digits)}$`;
}

export function parseRuns(jsonl: string): RunLine[] {
  return jsonl
    .split('\n')
    .filter((l) => l.trim() !== '')
    .map((l) => JSON.parse(l) as RunLine);
}

function randomRuns(runs: RunLine[]): Map<string, RunLine[]> {
  const by = new Map<string, RunLine[]>();
  for (const r of runs) {
    if (r.config.kind !== 'random') continue;
    const list = by.get(r.config.strategy) ?? [];
    list.push(r);
    by.set(r.config.strategy, list);
  }
  if (by.size === 0) throw new Error('no random runs found in runs.jsonl');
  return by;
}

const metric = (rs: RunLine[], name: string) => rs.map((r) => Number(r.metrics[name]));

export function randomTex(runs: RunLine[]): string {
  const by = randomRuns(runs);
  const out = [
    HEADER,
    '\\begin{tabular}{@{}lrrrrrr@{}}',
    '\\toprule',
    ' & Lost (\\%) & Surf.\\ (\\%) & Viol. & Payload (KB) & State (KB) & Conv. \\\\',
    '\\midrule',
  ];
  for (const st of strategies(by.keys())) {
    const rs = by.get(st)!;
    const conv = rs.filter((r) => r.metrics.converged === true).length;
    out.push(
      [
        LABEL[st] ?? st,
        pm(metric(rs, 'lossRate'), 100, 1),
        pm(metric(rs, 'surfacedRate'), 100, 1),
        pm(metric(rs, 'causalViolations'), 1, 1),
        pm(metric(rs, 'payloadBytes'), 1e-3, 1),
        pm(metric(rs, 'stateBytes'), 1e-3, 1),
        `${conv}/${rs.length}`,
      ].join(' & ') + ' \\\\',
    );
  }
  out.push('\\bottomrule', '\\end{tabular}', '');
  return out.join('\n');
}

export function byClassTex(runs: RunLine[]): string {
  const by = randomRuns(runs);
  const out = [HEADER, `\\begin{tabular}{@{}l${'r'.repeat(CLASSES.length)}@{}}`, '\\toprule'];
  out.push(` & ${CLASSES.join(' & ')} \\\\`, '\\midrule');
  for (const st of strategies(by.keys())) {
    const rs = by.get(st)!;
    const cells = CLASSES.map((c) => {
      const lost = rs.reduce((a, r) => a + (r.byClass[c]?.lost ?? 0), 0);
      const ops = rs.reduce((a, r) => a + (r.byClass[c]?.ops ?? 0), 0);
      return `${lost}/${ops}`;
    });
    out.push(`${LABEL[st] ?? st} & ${cells.join(' & ')} \\\\`);
  }
  out.push('\\bottomrule', '\\end{tabular}', '');
  return out.join('\n');
}

export function randomDat(runs: RunLine[]): string {
  const by = randomRuns(runs);
  const lines = ['label lossPct payloadKB stateKB'];
  for (const st of strategies(by.keys())) {
    const rs = by.get(st)!;
    lines.push(
      [
        LABEL[st] ?? st,
        (mean(metric(rs, 'lossRate')) * 100).toFixed(2),
        (mean(metric(rs, 'payloadBytes')) / 1000).toFixed(2),
        (mean(metric(rs, 'stateBytes')) / 1000).toFixed(2),
      ].join(' '),
    );
  }
  return `# ${HEADER.slice(2)}${lines.join('\n')}\n`;
}

function main(): void {
  const scenarioRows = parseScenarioTable(readFileSync(join(IN_DIR, 'results.md'), 'utf8'));
  const runs = parseRuns(readFileSync(join(IN_DIR, 'runs.jsonl'), 'utf8'));
  mkdirSync(OUT_DIR, { recursive: true });
  const files: Record<string, string> = {
    'scenarios.tex': scenariosTex(scenarioRows),
    'random.tex': randomTex(runs),
    'byclass.tex': byClassTex(runs),
    'random.dat': randomDat(runs),
  };
  for (const [name, text] of Object.entries(files)) writeFileSync(join(OUT_DIR, name), text);
  console.log(`wrote ${Object.keys(files).join(', ')} to ${OUT_DIR}`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) main();
